edits.oldText:
export function statusLabel(status: "open" | "closed") {
  if (status === "open") return "Open";
  if (status === "closed") return "Closed";
  return "Closed";
}

edits.newText:
const statusLabels = {
  open: "Open",
  closed: "Closed",
} as const;

export function statusLabel(status: keyof typeof statusLabels) {
  return statusLabels[status];
}
